
const vm=require('node:vm'),path=require('node:path'),ts=require(path.join(process.cwd(),'NEW APP/node_modules/typescript'));
const sources={"NEW APP/src/services/ws-client.ts":"import type { DashboardPayload, WsDataMessage } from \"@/types/dashboard\";\nimport {\n  applyPayloadToStore,\n  readStoredFarmId,\n  useDashboardStore,\n  writeStoredFarmId,\n} from \"@/store/dashboard-store\";\nimport { fetchDashboardData, fetchLanWsToken, fetchServers, wsUrl } from \"@/services/api-client\";\nimport { getPlayerFarmRecords, isMultiFarmEnabled, resolveActiveFarmId } from \"@/lib/farm-scope\";\nimport { setNotificationScope } from \"@/platform/notifications\";\nimport { buildAlertScopeKey, resolveSaveIdFromPayload } from \"@/platform/urgent-alerts\";\n\ntype Listener = () => void;\n\nlet socket: WebSocket | null = null;\nlet reconnectTimer: ReturnType<typeof setTimeout> | null = null;\nlet pollTimer: ReturnType<typeof setInterval> | null = null;\nlet lastFingerprint = \"\";\nlet started = false;\nlet ingestGeneration = 0;\nlet bootstrapPromise: Promise<void> | null = null;\n\nfunction fingerprint(msg: WsDataMessage): string {\n  return `${msg.serverId}:${msg.timestamp}:${msg.data?.lastUpdated ?? \"\"}`;\n}\n\n/** Align notification scope immediately on switch (watcher also syncs on payload). */\nfunction syncNotificationScopeForContext(\n  serverId: string | null | undefined,\n  farmId: number | null | undefined,\n  payload?: DashboardPayload | null,\n): void {\n  const saveId = resolveSaveIdFromPayload(payload ?? useDashboardStore.getState().payload);\n  setNotificationScope(buildAlertScopeKey(serverId, farmId, saveId));\n}\n\n/**\n * Keep activeFarmId valid for the payload (MP farm list + localStorage).\n * When the selected farm owns no fields/livestock, infer from ownership counts (legacy apiStorage).\n */\nexport function syncActiveFarmForPayload(payload: DashboardPayload | null | undefined): void {\n  if (!payload || payload.error) return;\n  const state = useDashboardStore.getState();\n  const farms = getPlayerFarmRecords(payload.farmInfo);\n  const serverId = state.activeServerId;\n  const mpFarmSwitch = isMultiFarmEnabled(payload.farmInfo);\n  const stored = mpFarmSwitch ? readStoredFarmId(serverId) : null;\n  const current = Number(state.activeFarmId ?? 0);\n  const ids = new Set(\n    farms\n      .map((f) => Number(f.id ?? f.farmId))\n      .filter((id) => Number.isFinite(id) && id > 0)\n  );\n\n  let preferred = current > 0 && (ids.size === 0 || ids.has(current)) ? current : 0;\n  if (!preferred && stored && (ids.size === 0 || ids.has(stored))) preferred = stored;\n  if (!preferred && farms.length > 0) {\n    const first = Number(farms[0].id ?? farms[0].farmId);\n    if (Number.isFinite(first) && first > 0) preferred = first;\n  }\n  if (!preferred) preferred = 1;\n\n  const next = resolveActiveFarmId({\n    preferred,\n    farms: payload.farmInfo,\n    fields: payload.fields,\n    animals: payload.animals,\n    vehicles: payload.vehicles,\n  });\n\n  if (state.activeFarmId !== next) {\n    state.setActiveFarmId(next);\n  }\n  if (mpFarmSwitch) {\n    writeStoredFarmId(serverId, next);\n  }\n}\n\nfunction ingestPayload(payload: DashboardPayload, expectedServerId?: string | null): void {\n  const active = useDashboardStore.getState().activeServerId;\n  if (expectedServerId && active && String(expectedServerId) !== String(active)) return;\n  applyPayloadToStore(payload);\n  syncActiveFarmForPayload(payload);\n}\n\nfunction handleMessage(raw: string) {\n  let msg: WsDataMessage;\n  try {\n    msg = JSON.parse(raw) as WsDataMessage;\n  } catch {\n    return;\n  }\n  if (msg.type !== \"data\" || !msg.data) return;\n  const active = useDashboardStore.getState().activeServerId;\n  if (active && msg.serverId !== active) return;\n  const fp = fingerprint(msg);\n  if (fp === lastFingerprint) return;\n  lastFingerprint = fp;\n  ingestPayload(msg.data, msg.serverId);\n}\n\nasync function pollOnce() {\n  const gen = ingestGeneration;\n  const serverId = useDashboardStore.getState().activeServerId;\n  try {\n    const data = await fetchDashboardData(serverId, { retry: false });\n    if (gen !== ingestGeneration) return;\n    if (serverId && useDashboardStore.getState().activeServerId !== serverId) return;\n    ingestPayload(data, serverId);\n    useDashboardStore.getState().setConnection(\"http\");\n  } catch {\n    if (gen !== ingestGeneration) return;\n    useDashboardStore.getState().setConnection(\"error\");\n  }\n}\n\n/** User-triggered refresh (helper panel / stale chip). Uses the shared retry policy once. */\nexport async function refreshDashboard(): Promise<void> {\n  const gen = ingestGeneration;\n  const serverId = useDashboardStore.getState().activeServerId;\n  try {\n    const data = await fetchDashboardData(serverId, { retry: true });\n    if (gen !== ingestGeneration) return;\n    if (serverId && useDashboardStore.getState().activeServerId !== serverId) return;\n    ingestPayload(data, serverId);\n    useDashboardStore\n      .getState()\n      .setConnection(socket?.readyState === WebSocket.OPEN ? \"ws\" : \"http\");\n  } catch {\n    if (gen !== ingestGeneration) return;\n    useDashboardStore.getState().setConnection(\"error\");\n  }\n}\n\n/** Switch server tab and load that save's payload (HTTP); WS continues filtering by activeServerId. */\nexport async function switchActiveServer(serverId: string): Promise<void> {\n  const state = useDashboardStore.getState();\n  if (String(state.activeServerId) === String(serverId)) return;\n  ingestGeneration += 1;\n  const gen = ingestGeneration;\n  lastFingerprint = \"\";\n  state.setActiveServerId(String(serverId));\n  state.setPayload(null);\n  const storedFarm = readStoredFarmId(serverId);\n  if (storedFarm) state.setActiveFarmId(storedFarm);\n  syncNotificationScopeForContext(serverId, storedFarm ?? state.activeFarmId, null);\n  try {\n    const data = await fetchDashboardData(serverId, { retry: true });\n    if (gen !== ingestGeneration) return;\n    if (useDashboardStore.getState().activeServerId !== String(serverId)) return;\n    ingestPayload(data, serverId);\n    syncNotificationScopeForContext(serverId, useDashboardStore.getState().activeFarmId, data);\n    useDashboardStore\n      .getState()\n      .setConnection(socket?.readyState === WebSocket.OPEN ? \"ws\" : \"http\");\n  } catch {\n    if (gen !== ingestGeneration) return;\n    useDashboardStore.getState().setConnection(\"error\");\n  }\n}\n\nexport function switchActiveFarm(farmId: number): void {\n  const id = Number(farmId);\n  if (!Number.isFinite(id) || id <= 0) return;\n  const state = useDashboardStore.getState();\n  state.setActiveFarmId(id);\n  writeStoredFarmId(state.activeServerId, id);\n  syncNotificationScopeForContext(state.activeServerId, id, state.payload);\n}\n\nfunction startHttpFallback() {\n  if (pollTimer) return;\n  void pollOnce();\n  pollTimer = setInterval(() => void pollOnce(), 8000);\n}\n\nfunction scheduleReconnect() {\n  if (reconnectTimer) return;\n  reconnectTimer = setTimeout(() => {\n    reconnectTimer = null;\n    void connectWebSocket();\n  }, 3000);\n}\n\nexport async function connectWebSocket() {\n  if (socket?.readyState === WebSocket.OPEN) return;\n  try {\n    socket?.close();\n  } catch {\n    /* ignore */\n  }\n\n  const token = await fetchLanWsToken();\n  socket = new WebSocket(wsUrl(token));\n\n  socket.addEventListener(\"open\", () => {\n    useDashboardStore.getState().setConnection(\"ws\");\n    if (pollTimer) {\n      clearInterval(pollTimer);\n      pollTimer = null;\n    }\n  });\n\n  socket.addEventListener(\"message\", (ev) => {\n    if (typeof ev.data === \"string\") handleMessage(ev.data);\n  });\n\n  socket.addEventListener(\"close\", () => {\n    useDashboardStore.getState().setConnection(\"connecting\");\n    startHttpFallback();\n    scheduleReconnect();\n  });\n\n  socket.addEventListener(\"error\", () => {\n    socket?.close();\n  });\n}\n\nexport async function bootstrapRealtime(onReady?: Listener) {\n  if (started && bootstrapPromise) return bootstrapPromise;\n  started = true;\n  bootstrapPromise = (async () => {\n    try {\n      const servers = await fetchServers();\n      useDashboardStore.getState().setServers(servers);\n      if (servers.length && !useDashboardStore.getState().activeServerId) {\n        useDashboardStore.getState().setActiveServerId(String(servers[0].id));\n      }\n\n      try {\n        const data = await fetchDashboardData(useDashboardStore.getState().activeServerId, { retry: true });\n        ingestPayload(data, useDashboardStore.getState().activeServerId);\n      } catch {\n        useDashboardStore.getState().setConnection(\"error\");\n      }\n\n      await connectWebSocket();\n      onReady?.();\n    } catch {\n      started = false;\n      bootstrapPromise = null;\n      useDashboardStore.getState().setConnection(\"error\");\n      throw new Error(\"bootstrap_failed\");\n    }\n  })();\n  await bootstrapPromise;\n}\n\nexport function stopRealtime() {\n  started = false;\n  bootstrapPromise = null;\n  if (reconnectTimer) clearTimeout(reconnectTimer);\n  if (pollTimer) clearInterval(pollTimer);\n  reconnectTimer = null;\n  pollTimer = null;\n  try {\n    socket?.close();\n  } catch {\n    /* ignore */\n  }\n  socket = null;\n}","NEW APP/src/services/api-client.ts":"import type { DashboardPayload, FarmDashServer } from \"@/types/dashboard\";\nimport { hasFarmDashApi } from \"@/services/electron-bridge\";\nimport { fetchWithRetry } from \"@/lib/ux-retry\";\n\n/** Electron dev API from `npm run start:dev` (see tools/app/start-dev-electron.mjs). */\nconst VITE_DEV_API_HOST =\n  (typeof import.meta.env.VITE_FARMDASH_API === \"string\" &&\n    import.meta.env.VITE_FARMDASH_API.trim()) ||\n  \"127.0.0.1:8766\";\n\nfunction isBrowserViteDev(): boolean {\n  return import.meta.env.DEV && !hasFarmDashApi();\n}\n\nfunction apiBase(): string {\n  return \"\";\n}\n\nfunction withServerId(url: string, serverId: string | null): string {\n  if (!serverId) return url;\n  const sep = url.includes(\"?\") ? \"&\" : \"?\";\n  return `${url}${sep}serverId=${encodeURIComponent(serverId)}`;\n}\n\nexport async function fetchDashboardData(\n  serverId: string | null,\n  options: { retry?: boolean } = {},\n): Promise<DashboardPayload> {\n  const res = await fetchWithRetry(\n    () => fetch(withServerId(`${apiBase()}/api/data`, serverId), { cache: \"no-store\" }),\n    { retry: options.retry === true },\n  );\n  if (!res.ok) throw new Error(`HTTP ${res.status}`);\n  return res.json() as Promise<DashboardPayload>;\n}\n\nexport async function fetchServers(): Promise<FarmDashServer[]> {\n  const res = await fetch(`${apiBase()}/api/servers`, { cache: \"no-store\" });\n  if (!res.ok) return [];\n  return res.json() as Promise<FarmDashServer[]>;\n}\n\nexport async function fetchLanWsToken(): Promise<string | null> {\n  try {\n    const res = await fetch(`${apiBase()}/api/lan-ws-token`, { cache: \"no-store\" });\n    if (!res.ok) return null;\n    const body = (await res.json()) as { token?: string };\n    return body.token ?? null;\n  } catch {\n    return null;\n  }\n}\n\nexport function wsUrl(token?: string | null): string {\n  // Vite :5173 proxies HTTP /api but not the root WebSocket upgrade — talk to dev Electron directly.\n  if (isBrowserViteDev()) {\n    const base = `ws://${VITE_DEV_API_HOST}`;\n    if (token) return `${base}?t=${encodeURIComponent(token)}`;\n    return base;\n  }\n  const proto = location.protocol === \"https:\" ? \"wss:\" : \"ws:\";\n  const base = `${proto}//${location.host}`;\n  if (token) return `${base}?t=${encodeURIComponent(token)}`;\n  return base;\n}","NEW APP/src/store/dashboard-store.ts":"import { create } from \"zustand\";\nimport type {\n  DashboardPayload,\n  FarmDashServer,\n  SectionId,\n  SectionParams,\n} from \"@/types/dashboard\";\nimport { normalizeSectionId } from \"@/types/dashboard\";\n\nconst LAST_SECTION_KEY = \"farmdash_last_section\";\nconst DEFAULT_SECTION_PREF_KEY = \"farmdash_default_section\";\n\nexport type DefaultSectionPref = \"overview\" | \"last\" | SectionId;\n\nexport interface DashboardState {\n  payload: DashboardPayload | null;\n  servers: FarmDashServer[];\n  activeServerId: string | null;\n  activeFarmId: number | null;\n  section: SectionId;\n  sectionParams: SectionParams;\n  /** Enabled dashboard sections from Settings (map always available). */\n  enabledSections: Partial<Record<string, boolean>>;\n  connection: \"connecting\" | \"ws\" | \"http\" | \"error\";\n  lastUpdated: string | null;\n  locale: string;\n\n  setPayload: (payload: DashboardPayload | null) => void;\n  setServers: (servers: FarmDashServer[]) => void;\n  setActiveServerId: (id: string | null) => void;\n  setActiveFarmId: (id: number | null) => void;\n  setSection: (section: SectionId, params?: SectionParams) => void;\n  setSectionParams: (params: SectionParams) => void;\n  clearSectionParams: () => void;\n  setEnabledSections: (sections: Partial<Record<string, boolean>>) => void;\n  setConnection: (connection: DashboardState[\"connection\"]) => void;\n  setLocale: (locale: string) => void;\n}\n\nfunction writeHash(section: SectionId, params: SectionParams) {\n  const parts = [`#/${section}`];\n  if (params.tab) parts[0] += `/${encodeURIComponent(params.tab)}`;\n  const q = new URLSearchParams();\n  if (params.filter) q.set(\"filter\", params.filter);\n  if (params.id) q.set(\"id\", params.id);\n  if (params.role) q.set(\"role\", params.role);\n  if (params.view) q.set(\"view\", params.view);\n  const qs = q.toString();\n  const hash = qs ? `${parts[0]}?${qs}` : parts[0];\n  if (typeof window !== \"undefined\" && window.location.hash !== hash) {\n    window.history.replaceState(null, \"\", hash);\n  }\n}\n\nfunction rememberSection(section: SectionId) {\n  try {\n    localStorage.setItem(LAST_SECTION_KEY, section);\n  } catch {\n    /* ignore */\n  }\n}\n\nexport function readLastSection(): SectionId | null {\n  try {\n    const raw = localStorage.getItem(LAST_SECTION_KEY);\n    return raw ? normalizeSectionId(raw) : null;\n  } catch {\n    return null;\n  }\n}\n\nexport function readDefaultSectionPref(): DefaultSectionPref {\n  try {\n    const raw = localStorage.getItem(DEFAULT_SECTION_PREF_KEY);\n    if (!raw) return \"last\";\n    if (raw === \"overview\" || raw === \"last\") return raw;\n    return normalizeSectionId(raw);\n  } catch {\n    return \"last\";\n  }\n}\n\nexport function writeDefaultSectionPref(pref: DefaultSectionPref) {\n  try {\n    localStorage.setItem(DEFAULT_SECTION_PREF_KEY, pref);\n  } catch {\n    /* ignore */\n  }\n}\n\nexport function parseLocationHash(): { section: SectionId; params: SectionParams } {\n  if (typeof window === \"undefined\") {\n    return { section: \"overview\", params: {} };\n  }\n  const raw = window.location.hash.replace(/^#\\/?/, \"\").trim();\n  if (!raw) {\n    const pref = readDefaultSectionPref();\n    if (pref === \"last\") {\n      return { section: readLastSection() || \"overview\", params: {} };\n    }\n    if (pref === \"overview\") return { section: \"overview\", params: {} };\n    return { section: normalizeSectionId(pref), params: {} };\n  }\n\n  const [pathPart, queryPart] = raw.split(\"?\");\n  const segments = pathPart.split(\"/\").filter(Boolean);\n  let section = normalizeSectionId(segments[0]);\n  const params: SectionParams = {};\n  if (segments[1]) params.tab = decodeURIComponent(segments[1]);\n\n  if (queryPart) {\n    const q = new URLSearchParams(queryPart);\n    // Legacy `#/economy?tab=redtape` (and similar) — path segment wins if both present.\n    const tabQ = q.get(\"tab\");\n    if (tabQ && !params.tab) params.tab = tabQ;\n    const filter = q.get(\"filter\");\n    const id = q.get(\"id\");\n    const role = q.get(\"role\");\n    const view = q.get(\"view\");\n    if (filter) params.filter = filter;\n    if (id) params.id = id;\n    if (role) params.role = role;\n    if (view) params.view = view;\n  }\n\n  // Legacy Economy deep links promote to first-class sections.\n  if (section === \"economy\" && params.tab === \"storage\") {\n    section = \"storage\";\n    delete params.tab;\n  }\n  if (section === \"economy\" && params.tab === \"redtape\") {\n    section = \"redtape\";\n    delete params.tab;\n  }\n  if (section === \"economy\" && params.tab === \"invoices\") {\n    section = \"invoices\";\n    delete params.tab;\n  }\n  if (section === \"economy\" && params.tab === \"hirepurchasing\") {\n    section = \"hirepurchasing\";\n    delete params.tab;\n  }\n\n  return { section, params };\n}\n\nconst initialRoute = parseLocationHash();\n// Normalize legacy `#/economy/storage` / `#/economy/redtape` / invoices|hirepurchasing in the address bar on boot.\nif (typeof window !== \"undefined\") {\n  writeHash(initialRoute.section, initialRoute.params);\n}\n\nexport const useDashboardStore = create<DashboardState>((set, get) => ({\n  payload: null,\n  servers: [],\n  activeServerId: null,\n  activeFarmId: null,\n  section: initialRoute.section,\n  sectionParams: initialRoute.params,\n  enabledSections: {},\n  connection: \"connecting\",\n  lastUpdated: null,\n  locale: localStorage.getItem(\"farmdash_locale\") || \"en\",\n\n  setPayload: (payload) =>\n    set((state) => ({\n      payload,\n      lastUpdated: payload?.lastUpdated ?? new Date().toISOString(),\n      connection: payload?.error ? \"error\" : state.connection === \"error\" ? \"http\" : state.connection,\n    })),\n  setServers: (servers) => set({ servers }),\n  setActiveServerId: (activeServerId) => set({ activeServerId }),\n  setActiveFarmId: (activeFarmId) => set({ activeFarmId }),\n  setSection: (section, params = {}) => {\n    const next = normalizeSectionId(section);\n    rememberSection(next);\n    writeHash(next, params);\n    set({ section: next, sectionParams: params });\n  },\n  setSectionParams: (params) => {\n    const { section } = get();\n    writeHash(section, params);\n    set({ sectionParams: params });\n  },\n  clearSectionParams: () => {\n    const { section } = get();\n    writeHash(section, {});\n    set({ sectionParams: {} });\n  },\n  setEnabledSections: (enabledSections) => set({ enabledSections }),\n  setConnection: (connection) => set({ connection }),\n  setLocale: (locale) => {\n    localStorage.setItem(\"farmdash_locale\", locale);\n    set({ locale });\n    // Keep i18n catalog locale in sync (dynamic import avoids circular deps at module init).\n    void import(\"@/i18n/i18n\").then((m) => m.setLocale(locale));\n  },\n}));\n\nexport function applyPayloadToStore(payload: DashboardPayload) {\n  useDashboardStore.getState().setPayload(payload);\n  if (!payload.error) {\n    useDashboardStore.getState().setConnection(\"ws\");\n  }\n}\n\nexport function farmStorageKey(serverId: string | null | undefined): string {\n  return `dashboard_active_farm_${String(serverId || \"default\")}`;\n}\n\nexport function readStoredFarmId(serverId: string | null | undefined): number | null {\n  try {\n    const raw = localStorage.getItem(farmStorageKey(serverId));\n    const n = Number(raw);\n    return Number.isFinite(n) && n > 0 ? n : null;\n  } catch {\n    return null;\n  }\n}\n\nexport function writeStoredFarmId(serverId: string | null | undefined, farmId: number): void {\n  try {\n    localStorage.setItem(farmStorageKey(serverId), String(farmId));\n  } catch {\n    /* ignore */\n  }\n}\n\n/** Sync store from browser hash (popstate / hashchange). */\nexport function syncSectionFromHash() {\n  const { section, params } = parseLocationHash();\n  const state = useDashboardStore.getState();\n  if (state.section === section && JSON.stringify(state.sectionParams) === JSON.stringify(params)) {\n    // Still normalize legacy `#/economy/storage` / `#/economy/redtape` / invoices|hirepurchasing URLs.\n    writeHash(section, params);\n    return;\n  }\n  rememberSection(section);\n  writeHash(section, params);\n  useDashboardStore.setState({ section, sectionParams: params });\n}","NEW APP/src/lib/livestock-fanout.ts":"import type { HusbandryPen, LodCluster, LivestockAnimal } from \"./livestock-types\";\nimport { sumClusterCounts } from \"./livestock-format\";\n\nexport const DEFAULT_PEN_HEAD_ROW_CAP = 4096;\nexport const DEFAULT_GLOBAL_ROW_CAP = 8000;\n\nexport interface LodCounter {\n  emitted: number;\n  trimmed: number;\n  capHit: boolean;\n  cap: number;\n}\n\nfunction isUnknownSubType(st: unknown): boolean {\n  if (st == null || st === \"\") return true;\n  const s = String(st).trim();\n  return s === \"\" || s.toLowerCase() === \"unknown\";\n}\n\nfunction resolveClusterSubType(c: LodCluster, husbandry: HusbandryPen): string {\n  if (!isUnknownSubType(c.subType)) return String(c.subType);\n  if (!isUnknownSubType(c.animalType)) return String(c.animalType);\n  if (husbandry && !isUnknownSubType(husbandry.animalTypeName)) {\n    return String(husbandry.animalTypeName);\n  }\n  return \"Unknown\";\n}\n\nfunction resolveClusterHealth(c: LodCluster, husbandry: HusbandryPen): number {\n  if (typeof c.avgHealth === \"number\" && Number.isFinite(c.avgHealth)) {\n    return Math.max(0, Math.min(100, c.avgHealth));\n  }\n  if (typeof husbandry.health === \"number\" && Number.isFinite(husbandry.health)) {\n    return Math.max(0, Math.min(100, husbandry.health));\n  }\n  return 100;\n}\n\nexport function resolveAnimalGroupHeadCount(animalGroup: LivestockAnimal | null | undefined): number {\n  if (!animalGroup) return 1;\n  const cc = Number(animalGroup.clusterCount);\n  if (animalGroup.__lodClusterAggregate && Number.isFinite(cc) && cc > 0) {\n    return Math.floor(cc);\n  }\n  const raw =\n    animalGroup.count != null\n      ? animalGroup.count\n      : animalGroup.numAnimals != null\n        ? animalGroup.numAnimals\n        : NaN;\n  const c = Number(raw);\n  if (Number.isFinite(c) && c > 0) return Math.floor(c);\n  return 1;\n}\n\nexport function shouldEmitClusterAggregateRow(animalGroup: LivestockAnimal | null | undefined): boolean {\n  if (!animalGroup) return false;\n  if (animalGroup.__lodClusterAggregate === true) return true;\n  if (String(animalGroup.type || \"\").toLowerCase() === \"cluster\") return true;\n  return resolveAnimalGroupHeadCount(animalGroup) > 1;\n}\n\nexport function isDetailClusterSummaryPen(husbandry: HusbandryPen | null | undefined): boolean {\n  if (!husbandry) return false;\n  const detailReady =\n    (husbandry.__detailHydrated === true || husbandry.lod === \"full\") &&\n    Array.isArray(husbandry.animals) &&\n    husbandry.animals.length > 0;\n  if (!detailReady) return false;\n  for (const a of husbandry.animals!) {\n    if (a?.uniqueId) return false;\n  }\n  for (const row of husbandry.animals!) {\n    if (shouldEmitClusterAggregateRow(row) && resolveAnimalGroupHeadCount(row) > 1) {\n      return true;\n    }\n  }\n  return false;\n}\n\n/**\n * When engine-reported heads disagree with RL-scaled cluster sums, rescale\n * bucket counts so fan-out / display totals match `numOfAnimalsReported`.\n */\nexport function reconcileClustersToReported(\n  clusters: LodCluster[] | null | undefined,\n  reportedHeads: number\n): LodCluster[] {\n  if (!Array.isArray(clusters) || clusters.length === 0) return [];\n  const target = Math.floor(Number(reportedHeads));\n  if (!Number.isFinite(target) || target <= 0) {\n    return clusters.map((c) => ({ ...c }));\n  }\n\n  const sum = sumClusterCounts(clusters);\n  if (sum === target) return clusters.map((c) => ({ ...c }));\n  if (sum <= 0) {\n    const first = clusters[0] || {};\n    return [{ ...first, count: target }];\n  }\n\n  const scale = target / sum;\n  const scaled = clusters.map((c) => {\n    const cc = Number(c?.count);\n    const exact = !Number.isFinite(cc) || cc <= 0 ? 0 : cc * scale;\n    const floor = Math.max(0, Math.floor(exact));\n    return { cluster: c, exact, floor, frac: exact - floor };\n  });\n  let used = scaled.reduce((a, r) => a + r.floor, 0);\n  let remain = target - used;\n  const order = scaled\n    .map((_, i) => i)\n    .sort((a, b) => scaled[b]!.frac - scaled[a]!.frac || scaled[b]!.floor - scaled[a]!.floor);\n  const counts = scaled.map((r) => r.floor);\n  for (const i of order) {\n    if (remain <= 0) break;\n    counts[i] = (counts[i] || 0) + 1;\n    remain -= 1;\n  }\n  if (remain < 0) {\n    for (const i of order) {\n      if (remain >= 0) break;\n      const take = Math.min(counts[i] || 0, -remain);\n      counts[i] = (counts[i] || 0) - take;\n      remain += take;\n    }\n  }\n  return clusters.map((c, i) => ({ ...c, count: Math.max(0, counts[i] || 0) }));\n}\n\n/**\n * Clusters for fan-out: prefer engine-reported total when it disagrees with\n * scaled RL bucket sums (Witcombe-style large pens).\n */\nexport function clustersForFanOut(\n  husbandry: HusbandryPen | null | undefined,\n  clusters: LodCluster[] | null | undefined\n): LodCluster[] {\n  if (!Array.isArray(clusters)) return [];\n  const reported = Number(husbandry?.numOfAnimalsReported);\n  if (!Number.isFinite(reported) || reported <= 0) {\n    return clusters.map((c) => ({ ...c }));\n  }\n  const sum = sumClusterCounts(clusters);\n  if (sum <= 0 || sum === Math.floor(reported)) {\n    return clusters.map((c) => ({ ...c }));\n  }\n  return reconcileClustersToReported(clusters, reported);\n}\n\nfunction animalGroupToClusterEntry(animalGroup: LivestockAnimal): LodCluster {\n  return {\n    count: resolveAnimalGroupHeadCount(animalGroup),\n    subType: animalGroup.subType || animalGroup.type || (animalGroup.animalType as string | undefined),\n    gender: animalGroup.gender,\n    avgHealth:\n      (animalGroup.avgHealth as number | undefined) != null\n        ? (animalGroup.avgHealth as number)\n        : animalGroup.health,\n    avgWeight:\n      (animalGroup.avgWeight as number | undefined) != null\n        ? (animalGroup.avgWeight as number)\n        : animalGroup.weight,\n    avgAgeMonths:\n      (animalGroup.avgAgeMonths as number | undefined) != null\n        ? (animalGroup.avgAgeMonths as number)\n        : (animalGroup.ageMonths as number | undefined) != null\n          ? (animalGroup.ageMonths as number)\n          : animalGroup.age,\n    ageMonths: (animalGroup.ageMonths as number | undefined) ?? animalGroup.age,\n    isLactating: animalGroup.isLactating,\n    isPregnant: animalGroup.isPregnant,\n  };\n}\n\nexport function stableAnimalRowId(\n  husbandryId: string | number | null | undefined,\n  uniqueId: string | number | null | undefined,\n  indexInPen: number\n): string {\n  const hid =\n    husbandryId != null && String(husbandryId) !== \"\" ? String(husbandryId) : \"pen\";\n  const uid =\n    uniqueId != null && String(uniqueId) !== \"\" ? String(uniqueId) : \"x\";\n  return `${hid}:${uid}:${indexInPen}`;\n}\n\nexport function looksLikeStableAnimalId(id: unknown): boolean {\n  if (typeof id !== \"string\" || !id.includes(\":\")) return false;\n  const parts = id.split(\":\");\n  if (parts.length < 3) return false;\n  return /^\\d+$/.test(parts[parts.length - 1] || \"\");\n}\n\nexport function fanOutClustersIndividualRows(\n  husbandry: HusbandryPen,\n  clusters: LodCluster[] | null | undefined,\n  farmId: number,\n  globalCounter?: LodCounter,\n  opts?: { penCap?: number; globalCap?: number; startHeadIndex?: number }\n): LivestockAnimal[] {\n  const out: LivestockAnimal[] = [];\n  if (!husbandry || !Array.isArray(clusters)) return out;\n\n  const penCap = Number.isFinite(opts?.penCap) ? Math.floor(opts!.penCap!) : DEFAULT_PEN_HEAD_ROW_CAP;\n  const globalCap = globalCounter && Number.isFinite(globalCounter.cap)\n    ? Math.floor(globalCounter.cap)\n    : Number.isFinite(opts?.globalCap)\n      ? Math.floor(opts!.globalCap!)\n      : DEFAULT_GLOBAL_ROW_CAP;\n  const startHeadIndex = Number.isFinite(opts?.startHeadIndex)\n    ? Math.max(0, Math.floor(opts!.startHeadIndex!))\n    : 0;\n\n  const huName = husbandry.name || husbandry.buildingName;\n  const huId = husbandry.id ?? husbandry.buildingId;\n\n  const clustersForEmit = clustersForFanOut(husbandry, clusters);\n\n  let headsThisPen = 0;\n  let trimmedHeads = 0;\n\n  outer: for (let ci = 0; ci < clustersForEmit.length; ci++) {\n    const c = clustersForEmit[ci];\n    if (!c || !c.count || c.count <= 0) continue;\n\n    const subType = resolveClusterSubType(c, husbandry);\n    const ageMonths =\n      typeof c.avgAgeMonths === \"number\"\n        ? c.avgAgeMonths\n        : typeof c.ageMonths === \"number\"\n          ? c.ageMonths\n          : (c.ageDecile || 0) * 12;\n    const avgHealth = resolveClusterHealth(c, husbandry);\n    const avgWeight = typeof c.avgWeight === \"number\" && c.avgWeight > 0 ? c.avgWeight : null;\n    const nTotal = Math.floor(Number(c.count)) || 0;\n\n    const genetics =\n      typeof c.avgGenFert === \"number\"\n        ? {\n            fertility: c.avgGenFert,\n            productivity: c.avgGenProd,\n            health: c.avgGenHealth,\n            metabolism: c.avgGenMetabolism,\n            quality: c.avgGenQuality,\n          }\n        : null;\n\n    for (let hi = 0; hi < nTotal; hi++) {\n      if (headsThisPen >= penCap) {\n        trimmedHeads += nTotal - hi;\n        for (let cj = ci + 1; cj < clustersForEmit.length; cj++) {\n          const cc = clustersForEmit[cj];\n          if (cc && cc.count && cc.count > 0) trimmedHeads += Math.floor(Number(cc.count)) || 0;\n        }\n        break outer;\n      }\n      if (globalCounter && (globalCounter.emitted || 0) >= globalCap) {\n        trimmedHeads += nTotal - hi;\n        for (let ck = ci + 1; ck < clustersForEmit.length; ck++) {\n          const cd = clustersForEmit[ck];\n          if (cd && cd.count && cd.count > 0) trimmedHeads += Math.floor(Number(cd.count)) || 0;\n        }\n        break outer;\n      }\n\n      // Pen-wide index (startHeadIndex + headsThisPen) — never reset per cluster group.\n      const id = stableAnimalRowId(huId, null, startHeadIndex + headsThisPen);\n      out.push({\n        id,\n        name: String(subType),\n        husbandryName: huName,\n        husbandryId: huId,\n        ownerFarmId: husbandry.ownerFarmId || husbandry.farmId,\n        farmId,\n        age: ageMonths,\n        health: avgHealth,\n        weight: avgWeight != null ? avgWeight : 0,\n        gender: c.gender || \"female\",\n        subType,\n        animalTypeName: husbandry.animalTypeName || undefined,\n        location: huName,\n        locationType: \"pasture\",\n        isLactating: !!c.isLactating,\n        isPregnant: !!c.isPregnant,\n        isParent: false,\n        genetics,\n        productivity: c.avgGenProd != null ? c.avgGenProd : null,\n        __lodSynth: true,\n        __lodSynthEstimate: true,\n      });\n      headsThisPen += 1;\n      if (globalCounter) globalCounter.emitted = (globalCounter.emitted || 0) + 1;\n    }\n  }\n\n  if (trimmedHeads > 0) {\n    husbandry.__lodTrimmed = trimmedHeads;\n    if (globalCounter) globalCounter.trimmed = (globalCounter.trimmed || 0) + trimmedHeads;\n  }\n  if (globalCounter && (globalCounter.emitted || 0) >= globalCap) {\n    globalCounter.capHit = true;\n  }\n  return out;\n}\n\nexport function fanOutAnimalGroupsIndividualRows(\n  husbandry: HusbandryPen,\n  groups: LivestockAnimal[] | null | undefined,\n  farmId: number,\n  globalCounter?: LodCounter,\n  opts?: { penCap?: number; globalCap?: number; startHeadIndex?: number }\n): LivestockAnimal[] {\n  if (!husbandry || !Array.isArray(groups)) return [];\n  const clusters: LodCluster[] = [];\n  for (const g of groups) {\n    if (!shouldEmitClusterAggregateRow(g)) continue;\n    const heads = resolveAnimalGroupHeadCount(g);\n    if (heads <= 1) continue;\n    clusters.push(animalGroupToClusterEntry(g));\n  }\n  return fanOutClustersIndividualRows(husbandry, clusters, farmId, globalCounter, opts);\n}","NEW APP/src/lib/livestock-format.ts":"import type { LivestockAnimal } from \"./livestock-types\";\n\n/** Minimal row shape for head counting (flattened animals or pasture rows). */\nexport type LivestockHeadLike = {\n  __emptyPen?: boolean;\n  __lodClusterAggregate?: boolean;\n  clusterCount?: number | string;\n};\n\n/** Minimal husbandry/pen shape for authoritative head counts. */\nexport type HusbandryHeadLike = {\n  numOfAnimalsReported?: number;\n  animalCount?: number;\n  numAnimals?: number;\n  clusters?: Array<{ count?: number } | null | undefined> | null;\n  animals?: LivestockHeadLike[] | null;\n  livestock?: LivestockHeadLike[] | null;\n  animalList?: LivestockHeadLike[] | null;\n};\n\nexport function isUnknownSubTypeLabel(subType: unknown): boolean {\n  if (subType == null || subType === \"\") return true;\n  return String(subType).trim().toLowerCase() === \"unknown\";\n}\n\nexport function resolveAnimalSubTypeRaw(animal: LivestockAnimal | null | undefined): string {\n  if (!animal) return \"\";\n  if (!isUnknownSubTypeLabel(animal.subType)) return String(animal.subType);\n  if (!isUnknownSubTypeLabel(animal.animalTypeName)) return String(animal.animalTypeName);\n  if (!isUnknownSubTypeLabel(animal.type) && animal.type !== \"cluster\") {\n    return String(animal.type);\n  }\n  return \"\";\n}\n\n/** Pastures drilldown uses the same <70 threshold; skip LOD rows with no health telemetry. */\nexport function isLivestockLowHealthRow(animal: LivestockAnimal): boolean {\n  if (!animal || animal.__emptyPen) return false;\n  const health = Number(animal.health ?? 0);\n  if (!Number.isFinite(health) || health >= 70) return false;\n  if (\n    health <= 0 &&\n    (animal.__lodSynth || animal.__lodSynthEstimate) &&\n    Number(animal.weight ?? 0) <= 0\n  ) {\n    return false;\n  }\n  return true;\n}\n\nexport function shouldShowHealthErrorBadge(animal: LivestockAnimal): boolean {\n  if (!animal || animal.health !== 0) return false;\n  if (animal.__lodSynth || animal.__lodSynthEstimate || animal.__lodClusterAggregate) {\n    return false;\n  }\n  return true;\n}\n\nexport function displayAnimalHealth(animal: LivestockAnimal | null | undefined): number {\n  const h = Number(animal?.health);\n  if (Number.isFinite(h) && h > 0) return h;\n  if (animal?.__lodSynth || animal?.__lodClusterAggregate || animal?.__lodSynthEstimate) {\n    return 100;\n  }\n  return Number.isFinite(h) ? h : 100;\n}\n\nexport function roundAgeMonths(m: unknown): number {\n  const n = Number(m);\n  if (!Number.isFinite(n)) return 0;\n  return Math.abs(n - Math.round(n)) < 0.001 ? Math.round(n) : Math.round(n * 10) / 10;\n}\n\nexport function getHealthClass(health: number): string {\n  if (health >= 80) return \"health-excellent\";\n  if (health >= 60) return \"health-good\";\n  if (health >= 40) return \"health-average\";\n  if (health >= 20) return \"health-poor\";\n  return \"health-critical\";\n}\n\nexport function capitalize(str: string): string {\n  if (!str) return \"\";\n  return str.charAt(0).toUpperCase() + str.slice(1).toLowerCase();\n}\n\nexport function formatAnimalType(subType: string, unknownLabel = \"Unknown\"): string {\n  if (isUnknownSubTypeLabel(subType)) return unknownLabel;\n  const parts = subType.split(\"_\");\n  if (parts.length > 1) {\n    const type = parts[0].toLowerCase();\n    const breed = parts\n      .slice(1)\n      .join(\" \")\n      .toLowerCase()\n      .replace(/\\b\\w/g, (l) => l.toUpperCase());\n    return `${breed} ${capitalize(type)}`;\n  }\n  return capitalize(subType);\n}\n\nexport function resolveAnimalLocationLabel(animal: LivestockAnimal | null | undefined): string {\n  if (!animal || typeof animal !== \"object\") return \"Unknown\";\n  const direct = String(animal.location || \"\").trim();\n  if (direct && direct.toLowerCase() !== \"unknown\") return direct;\n  const husbandry = String(animal.husbandryName || \"\").trim();\n  if (husbandry && husbandry.toLowerCase() !== \"unknown\") return husbandry;\n  return \"Unknown\";\n}\n\nexport function resolveAnimalLocationType(animal: LivestockAnimal | null | undefined): string {\n  if (!animal || typeof animal !== \"object\") return \"unknown\";\n  const direct = String(animal.locationType || \"\").trim();\n  if (direct && direct.toLowerCase() !== \"unknown\") return direct;\n  const husbandry = String(animal.husbandryName || \"\").trim();\n  return husbandry ? \"Livestock Building\" : \"unknown\";\n}\n\nexport function locationBadgeTone(\n  locationType: string\n): \"default\" | \"accent\" | \"warn\" | \"danger\" {\n  if (locationType.includes(\"Cow\")) return \"accent\";\n  if (locationType.includes(\"Pig\")) return \"warn\";\n  if (locationType.includes(\"Chicken\")) return \"default\";\n  if (locationType.includes(\"Sheep\")) return \"default\";\n  return \"default\";\n}\n\nexport function animalTypeKey(animal: LivestockAnimal): string {\n  const raw = resolveAnimalSubTypeRaw(animal);\n  if (!raw) return \"\";\n  return raw.split(\"_\")[0] || \"\";\n}\n\nexport function headCount(animal: LivestockHeadLike | null | undefined): number {\n  if (!animal || animal.__emptyPen) return 0;\n  const c = Number(animal.clusterCount);\n  if (animal.__lodClusterAggregate && Number.isFinite(c) && c > 0) return Math.floor(c);\n  return 1;\n}\n\n/**\n * Heads on farm from flattened livestock rows.\n * Cluster LOD aggregate rows count as `clusterCount`; empty-pen stubs are excluded.\n * Overview / badges must use this — not `animals.length` (row count ≠ herd size).\n */\nexport function countLivestockHeads(\n  animals: Array<LivestockHeadLike | null | undefined> | null | undefined\n): number {\n  if (!Array.isArray(animals)) return 0;\n  let n = 0;\n  for (const a of animals) {\n    if (!a || a.__emptyPen) continue;\n    n += headCount(a);\n  }\n  return n;\n}\n\n/** Sum of cluster bucket counts (may be RL-sampled + scaled). */\nexport function sumClusterCounts(\n  clusters: Array<{ count?: number } | null | undefined> | null | undefined\n): number {\n  if (!Array.isArray(clusters)) return 0;\n  let sum = 0;\n  for (const c of clusters) {\n    const cc = Number(c?.count);\n    if (Number.isFinite(cc) && cc > 0) sum += Math.floor(cc);\n  }\n  return sum;\n}\n\n/**\n * Authoritative pen head count.\n * Prefer `numOfAnimalsReported` (engine getNumOfAnimals) when it disagrees with\n * scaled RL cluster sums / animalCount — sampling scale can overshoot or undershoot.\n */\nexport function husbandryHeadCount(\n  husbandry: HusbandryHeadLike | null | undefined\n): number {\n  if (!husbandry || typeof husbandry !== \"object\") return 0;\n\n  const reported = Number(husbandry.numOfAnimalsReported);\n  if (Number.isFinite(reported) && reported > 0) return Math.floor(reported);\n\n  const direct = Number(husbandry.animalCount ?? husbandry.numAnimals ?? 0);\n  if (Number.isFinite(direct) && direct > 0) return Math.floor(direct);\n\n  const clusterSum = sumClusterCounts(husbandry.clusters);\n  if (clusterSum > 0) return clusterSum;\n\n  // Nested animal/group lists (detail / placeable shapes)\n  const lists = [husbandry.animals, husbandry.livestock, husbandry.animalList].filter(\n    Array.isArray\n  ) as LivestockHeadLike[][];\n  let nested = 0;\n  for (const list of lists) {\n    nested += countLivestockHeads(list);\n  }\n  return nested;\n}\n\n/**\n * Display barn capacity: prefer `maxAnimals` (getMaxNumOfAnimals).\n * `capacity` from getCapacity() is often fill/storage liters — not animal slots.\n */\nexport function resolvePastureDisplayCapacity(\n  husbandry:\n    | {\n        maxAnimals?: number;\n        capacity?: number;\n        name?: string;\n        buildingName?: string;\n        filename?: string;\n      }\n    | null\n    | undefined,\n  estimateFromName: (name: string | null | undefined) => number\n): number {\n  const maxA = Number(husbandry?.maxAnimals);\n  if (Number.isFinite(maxA) && maxA > 0) return Math.floor(maxA);\n\n  // Only trust capacity when it looks like animal slots (not food fill liters).\n  const cap = Number(husbandry?.capacity);\n  if (Number.isFinite(cap) && cap > 0 && cap <= 500) return Math.floor(cap);\n\n  const name =\n    husbandry?.filename ||\n    husbandry?.name ||\n    husbandry?.buildingName ||\n    null;\n  return estimateFromName(name);\n}\n\n/** Prefer RL ear tag (`uniqueId`); fall back to stable row id. */\nexport function animalEarTag(animal: LivestockAnimal | null | undefined): string {\n  if (!animal) return \"\";\n  if (animal.uniqueId != null && String(animal.uniqueId) !== \"\") {\n    return String(animal.uniqueId);\n  }\n  return animal.id != null ? String(animal.id) : \"\";\n}\n\n/**\n * Display tag for tables/panels. When the same ear tag appears more than once\n * in `animalsInView`, append the pen index from the stable row id.\n */\nexport function displayAnimalEarTag(\n  animal: LivestockAnimal,\n  animalsInView?: LivestockAnimal[] | null\n): string {\n  const tag = animalEarTag(animal);\n  if (!tag) return \"\";\n  if (animal.uniqueId == null || String(animal.uniqueId) === \"\") return tag;\n  if (!animalsInView?.length) return tag;\n  const uid = String(animal.uniqueId);\n  const dupCount = animalsInView.filter(\n    (a) => a.uniqueId != null && String(a.uniqueId) === uid\n  ).length;\n  if (dupCount <= 1) return tag;\n  const parts = String(animal.id ?? \"\").split(\":\");\n  const penIdx = parts.length >= 3 ? parts[parts.length - 1] : \"\";\n  return penIdx !== \"\" ? `${tag}·${penIdx}` : tag;\n}\n\nexport function livestockTableRowId(\n  row: LivestockAnimal,\n  index: number\n): string {\n  if (row?.id != null && String(row.id) !== \"\") return String(row.id);\n  return `row-${index}`;\n}\n\n/** Match by stable row `id` first (string-safe; no parseInt). */\nexport function findAnimalById(\n  animals: LivestockAnimal[],\n  animalId: string | number\n): LivestockAnimal | undefined {\n  const target = String(animalId);\n  const byStable = animals.find((a) => String(a.id) === target);\n  if (byStable) return byStable;\n  // Legacy / ambiguous: only accept uniqueId match when unambiguous in the list.\n  const byTag = animals.filter(\n    (a) => a.uniqueId != null && String(a.uniqueId) === target\n  );\n  return byTag.length === 1 ? byTag[0] : undefined;\n}\n\nexport function reproductionRate(animal: LivestockAnimal): number {\n  if (animal.reproduction != null && !Number.isNaN(Number(animal.reproduction))) {\n    return Number(animal.reproduction);\n  }\n  if (animal.genetics?.fertility != null && !Number.isNaN(Number(animal.genetics.fertility))) {\n    return Number(animal.genetics.fertility);\n  }\n  return 0;\n}","NEW APP/src/lib/ux-classify.ts":"/**\n * Shared error classification (NEW APP). Keep in lockstep with\n * FS25_FarmDashboard_App/web/assests/js/ux-classify.js.\n */\n\nexport const ERROR_CODES = {\n  E_CONFIG_INCOMPLETE: \"E_CONFIG_INCOMPLETE\",\n  E_AUTH_MISSING: \"E_AUTH_MISSING\",\n  E_INVALID_TOKEN: \"E_INVALID_TOKEN\",\n  E_LAN_BLOCKED: \"E_LAN_BLOCKED\",\n  E_LAN_TIMEOUT: \"E_LAN_TIMEOUT\",\n  E_SETUP_LOCAL_ONLY: \"E_SETUP_LOCAL_ONLY\",\n  E_SERVER_OFFLINE: \"E_SERVER_OFFLINE\",\n  E_LUA_STALE: \"E_LUA_STALE\",\n  E_MOD_MISSING: \"E_MOD_MISSING\",\n  E_MOD_OUTDATED: \"E_MOD_OUTDATED\",\n  E_PATH_DENIED: \"E_PATH_DENIED\",\n  E_PERMISSION_DENIED: \"E_PERMISSION_DENIED\",\n  E_CACHE_FALLBACK: \"E_CACHE_FALLBACK\",\n  E_NETWORK: \"E_NETWORK\",\n  E_SAVE_FAILED: \"E_SAVE_FAILED\",\n} as const;\n\nexport const NEXT_ACTION: Record<string, string> = {\n  E_CONFIG_INCOMPLETE: \"add_server\",\n  E_AUTH_MISSING: \"open_setup\",\n  E_INVALID_TOKEN: \"reset_token\",\n  E_LAN_BLOCKED: \"enable_firewall\",\n  E_LAN_TIMEOUT: \"rehandshake\",\n  E_SETUP_LOCAL_ONLY: \"open_setup\",\n  E_SERVER_OFFLINE: \"start_game\",\n  E_LUA_STALE: \"restart_game\",\n  E_MOD_MISSING: \"check_mod\",\n  E_MOD_OUTDATED: \"check_mod\",\n  E_PATH_DENIED: \"verify_save_slot\",\n  E_PERMISSION_DENIED: \"verify_save_slot\",\n  E_CACHE_FALLBACK: \"rehandshake\",\n  E_NETWORK: \"rehandshake\",\n  E_SAVE_FAILED: \"open_setup\",\n};\n\nconst SAVE_COPY: Record<string, { key: string; fallback: string }> = {\n  E_INVALID_TOKEN: {\n    key: \"setup.errToken\",\n    fallback: \"Setup token expired. Reload this page and try again.\",\n  },\n  E_AUTH_MISSING: {\n    key: \"setup.errAuth\",\n    fallback: \"Username or password rejected by the server.\",\n  },\n  E_SERVER_OFFLINE: {\n    key: \"setup.errNetwork\",\n    fallback:\n      \"Server unreachable. Check the host and port and confirm the dedicated server or FTP service is running.\",\n  },\n  E_NETWORK: {\n    key: \"setup.errNetwork\",\n    fallback:\n      \"Server unreachable. Check the host and port and confirm the dedicated server or FTP service is running.\",\n  },\n  E_LAN_TIMEOUT: {\n    key: \"setup.errLanTimeout\",\n    fallback:\n      \"LAN login did not finish in time. Check Wi‑Fi, confirm the PC app is running, then retry.\",\n  },\n  E_SETUP_LOCAL_ONLY: {\n    key: \"setup.errLocalOnly\",\n    fallback: \"Setup is only available on the PC running Farm Dashboard.\",\n  },\n  E_PATH_DENIED: {\n    key: \"setup.errPath\",\n    fallback: \"Save folder not found. Confirm the save has been loaded once with the FS25 mod enabled.\",\n  },\n  E_PERMISSION_DENIED: {\n    key: \"setup.errPath\",\n    fallback: \"Save folder not found. Confirm the save has been loaded once with the FS25 mod enabled.\",\n  },\n};\n\nexport function classifyHttpStatus(status: number): string {\n  const n = Number(status);\n  if (n === 401 || n === 403) return ERROR_CODES.E_AUTH_MISSING;\n  if (n === 404 || n >= 500) return ERROR_CODES.E_SERVER_OFFLINE;\n  if (n === 0 || !Number.isFinite(n)) return ERROR_CODES.E_NETWORK;\n  return ERROR_CODES.E_NETWORK;\n}\n\nexport function classifyRawError(rawMsg: string | null | undefined): string {\n  const s = String(rawMsg || \"\").toLowerCase();\n  if (/e_lan_timeout|lan.?timeout/.test(s)) return ERROR_CODES.E_LAN_TIMEOUT;\n  if (/e_setup_local|setup is only available|local-only/.test(s)) {\n    return ERROR_CODES.E_SETUP_LOCAL_ONLY;\n  }\n  if (/token/.test(s)) return ERROR_CODES.E_INVALID_TOKEN;\n  if (/eacces|permission denied|eperm/.test(s)) return ERROR_CODES.E_PERMISSION_DENIED;\n  if (/auth|unauthor|forbidden|403|401|denied|password|user/.test(s)) {\n    return ERROR_CODES.E_AUTH_MISSING;\n  }\n  if (/econn|enotfound|etimedout|timeout|unreachable|refused|network/.test(s)) {\n    return ERROR_CODES.E_SERVER_OFFLINE;\n  }\n  if (/enoent|not.?found|missing|path|directory|folder/.test(s)) {\n    return ERROR_CODES.E_PATH_DENIED;\n  }\n  if (/stale|lua/.test(s)) return ERROR_CODES.E_LUA_STALE;\n  return ERROR_CODES.E_SAVE_FAILED;\n}\n\nexport function nextActionForCode(code: string | null | undefined): string {\n  return NEXT_ACTION[String(code || \"\")] || \"open_setup\";\n}\n\nexport function saveCopyForCode(code: string | null | undefined): { key: string; fallback: string } | null {\n  return SAVE_COPY[String(code || \"\")] || null;\n}\n\nexport function mapSaveError(\n  rawMsg: string,\n  translate: (key: string, params?: Record<string, string | number> | null, fallback?: string) => string,\n): string {\n  const code = classifyRawError(rawMsg);\n  const copy = saveCopyForCode(code);\n  if (copy) return translate(copy.key, null, copy.fallback);\n  return translate(\"setup.toastCouldNotSave\", { msg: rawMsg }, `Could not save: ${rawMsg}`);\n}","NEW APP/src/services/lan-auth.ts":"/** LAN HTTP Basic auth for remote / tablet viewers. */\n\nconst STORAGE_KEY = \"farmdash_lan_http_basic_v1\";\n\nexport const LAN_AUTH_GATE_TIMEOUT_MS = 30_000;\n\nconst lanGateWaiters: Array<() => void> = [];\n\nfunction getLanHttpBasicStoredToken(): string {\n  try {\n    return sessionStorage.getItem(STORAGE_KEY) || localStorage.getItem(STORAGE_KEY) || \"\";\n  } catch {\n    try {\n      return sessionStorage.getItem(STORAGE_KEY) || \"\";\n    } catch {\n      return \"\";\n    }\n  }\n}\n\nfunction setLanHttpBasicStoredToken(token: string): void {\n  if (!token) return;\n  try {\n    sessionStorage.setItem(STORAGE_KEY, token);\n  } catch {\n    /* ignore */\n  }\n  try {\n    localStorage.setItem(STORAGE_KEY, token);\n  } catch {\n    /* ignore */\n  }\n}\n\nfunction clearLanHttpBasicStoredToken(): void {\n  try {\n    sessionStorage.removeItem(STORAGE_KEY);\n  } catch {\n    /* ignore */\n  }\n  try {\n    localStorage.removeItem(STORAGE_KEY);\n  } catch {\n    /* ignore */\n  }\n}\n\nfunction encodeBasicCredentials(user: string, pass: string): string {\n  const str = `${String(user)}:${String(pass)}`;\n  try {\n    const bytes = new TextEncoder().encode(str);\n    let bin = \"\";\n    for (let i = 0; i < bytes.length; i += 1) {\n      bin += String.fromCharCode(bytes[i]!);\n    }\n    return btoa(bin);\n  } catch {\n    try {\n      return btoa(unescape(encodeURIComponent(str)));\n    } catch {\n      return \"\";\n    }\n  }\n}\n\nfunction resolveLanGateWaiters(): void {\n  while (lanGateWaiters.length > 0) {\n    const r = lanGateWaiters.shift();\n    try {\n      r?.();\n    } catch {\n      /* ignore */\n    }\n  }\n}\n\nfunction hostnameImpliesLocalDashboard(): boolean {\n  try {\n    const h = String(window.location?.hostname ?? \"\").toLowerCase();\n    return !h || h === \"localhost\" || h === \"127.0.0.1\" || h === \"::1\" || h === \"[::1]\";\n  } catch {\n    return true;\n  }\n}\n\nfunction shouldAttachLanBasicToUrl(urlStr: string): boolean {\n  if (hostnameImpliesLocalDashboard()) return false;\n  try {\n    const u = new URL(urlStr, window.location.origin);\n    if (u.origin !== window.location.origin) return false;\n    return u.pathname.startsWith(\"/api/\");\n  } catch {\n    return false;\n  }\n}\n\nexport function farmdashSetLanHttpBasic(user: string, pass: string): void {\n  const tok = encodeBasicCredentials(user, pass);\n  if (tok) setLanHttpBasicStoredToken(tok);\n}\n\nexport function farmdashClearLanHttpBasic(): void {\n  clearLanHttpBasicStoredToken();\n}\n\nexport function farmdashHasLanHttpBasic(): boolean {\n  return !!getLanHttpBasicStoredToken();\n}\n\nexport function farmdashWaitForLanHttpBasicIfNeeded(options: { timeoutMs?: number } = {}): Promise<void> {\n  if (typeof globalThis === \"undefined\" || typeof globalThis.window === \"undefined\") return Promise.resolve();\n  if (!globalThis.window.__farmDashRemoteViewer) return Promise.resolve();\n  const waitMs = Number.isFinite(Number(options.timeoutMs))\n    ? Number(options.timeoutMs)\n    : LAN_AUTH_GATE_TIMEOUT_MS;\n  return new Promise((resolve) => {\n    let settled = false;\n    const done = () => {\n      if (settled) return;\n      settled = true;\n      resolve();\n    };\n    const timer = globalThis.window.setTimeout(() => {\n      try {\n        globalThis.document?.body?.classList.add(\"farmdash-lan-auth-timeout\");\n        globalThis.sessionStorage?.setItem(\"farmdash_last_error_code\", \"E_LAN_TIMEOUT\");\n      } catch {\n        /* ignore */\n      }\n      done();\n    }, waitMs);\n    lanGateWaiters.push(() => {\n      globalThis.window.clearTimeout(timer);\n      done();\n    });\n  });\n}\n\nexport function resolveLanAuthGate(): void {\n  resolveLanGateWaiters();\n}\n\nexport async function probeRemoteDashboardBootstrap(\n  fetchImpl: typeof fetch = fetch,\n  baseOrigin = \"\",\n): Promise<boolean> {\n  try {\n    const base = String(baseOrigin || \"\").trim();\n    if (!base) return false;\n    const status = await fetchImpl(`${base}/api/status`, { cache: \"no-store\", method: \"GET\" });\n    if (!status.ok) return false;\n    const servers = await fetchImpl(`${base}/api/servers`, { cache: \"no-store\", method: \"GET\" });\n    return servers.ok;\n  } catch {\n    return false;\n  }\n}\n\nexport type LanVerifyKind = \"ok\" | \"auth\" | \"network\";\n\nexport function interpretLanVerifyResult(status: number, networkError = false): LanVerifyKind {\n  if (networkError) return \"network\";\n  const n = Number(status);\n  if (n === 401 || n === 403) return \"auth\";\n  if (n >= 200 && n < 300) return \"ok\";\n  return \"network\";\n}\n\nexport async function verifyLanCredentials(): Promise<{ ok: boolean; status: number; kind: LanVerifyKind }> {\n  try {\n    const r = await fetch(`${window.location.origin}/api/servers`, {\n      cache: \"no-store\",\n      method: \"GET\",\n    });\n    const status = Number(r.status) || 0;\n    const kind = interpretLanVerifyResult(status, false);\n    return { ok: kind === \"ok\", status, kind };\n  } catch {\n    return { ok: false, status: 0, kind: \"network\" };\n  }\n}\n\nexport function installLanHttpBasicFetchPatch(): void {\n  if (typeof window === \"undefined\" || window.__farmdashLanFetchPatched) return;\n  window.__farmdashLanFetchPatched = true;\n  const orig = window.fetch.bind(window);\n  window.fetch = function patchedFetch(input: RequestInfo | URL, init?: RequestInit) {\n    const nextInit: RequestInit = init ? { ...init } : {};\n    const headers = new Headers(nextInit.headers || {});\n    const url =\n      typeof input === \"string\"\n        ? input\n        : input instanceof URL\n          ? input.href\n          : input.url;\n    if (shouldAttachLanBasicToUrl(url) && !headers.has(\"Authorization\")) {\n      const tok = getLanHttpBasicStoredToken();\n      if (tok) headers.set(\"Authorization\", `Basic ${tok}`);\n    }\n    nextInit.headers = headers;\n    return orig(input, nextInit);\n  };\n}\n\n/** Mark remote viewer when hostname is not loopback / Electron local. */\nexport function detectAndMarkRemoteViewer(): boolean {\n  if (typeof window === \"undefined\") return false;\n  if (typeof window.__farmDashRemoteViewer === \"boolean\") {\n    return window.__farmDashRemoteViewer;\n  }\n  const h = String(window.location?.hostname ?? \"\").toLowerCase();\n  const local =\n    !h ||\n    h === \"localhost\" ||\n    h === \"127.0.0.1\" ||\n    h === \"::1\" ||\n    h === \"[::1]\" ||\n    window.location.protocol === \"file:\";\n  window.__farmDashRemoteViewer = !local || h === \"demo.farmdashboard.co.uk\";\n  return !!window.__farmDashRemoteViewer;\n}"};
